import {monthLabel,paymentLabels,statuses} from './domain.js';
import {createPreviewService} from './preview-workflow.js';
export const poStatusLabels=statuses;
export const itemStatusLabels={pending:'รออนุมัติ',returned:'ส่งกลับแก้ไข',revision_requested:'ขอแก้ไข',editing:'รอแก้ไข',approved:'รอรับสินค้า',received:'รับสินค้าแล้ว',rejected:'ไม่อนุมัติ'};
const itemEligible=item=>['approved','received'].includes(item.state);
export async function buildPreviewWorkbook(report,month,ExcelJS=globalThis.ExcelJS){
 if(!ExcelJS)throw Error('ส่วนสร้างไฟล์ Excel โหลดไม่สำเร็จ กรุณารีโหลดหน้าแล้วลองอีกครั้ง');
 const workbook=new ExcelJS.Workbook();workbook.creator='PO The Grands — Preview';workbook.created=new Date();
 const summary=workbook.addWorksheet('สรุปรายเดือน',{views:[{state:'frozen',ySplit:4}]});summary.columns=[{width:30},{width:24}];summary.addRow(['PO The Grands']);summary.addRow(['สรุปประจำเดือน',monthLabel(month)]);summary.addRow(['เกณฑ์ยอดสั่งซื้อ','ยอดจริงรายการที่อนุมัติหรือรับแล้ว']);summary.addRow([]);summary.addRows([['ยอดสั่งซื้อรวม',report.total_cents/100],['จำนวนใบที่อนุมัติแล้ว',report.ordered_count],['รออนุมัติ',report.pending_count],['ไม่อนุมัติ',report.rejected_count]]);summary.getCell('B5').numFmt='฿#,##0.00';summary.getRow(1).font={bold:true,size:18,color:{argb:'FF164B49'}};summary.getRow(2).font={bold:true};summary.getRow(3).font={italic:true,color:{argb:'FF5A6C70'}};
 const sheet=workbook.addWorksheet('รายการสินค้า',{views:[{state:'frozen',ySplit:1}]});sheet.columns=[{header:'เลข PO',key:'po',width:21},{header:'วันที่ PO',key:'date',width:14},{header:'ผู้ขอ',key:'requester',width:20},{header:'แผนก/สาขา',key:'department',width:20},{header:'สถานะ PO',key:'status',width:22},{header:'สถานะรายการ',key:'itemStatus',width:20},{header:'สินค้า',key:'name',width:28},{header:'รายละเอียด / สเปค',key:'spec',width:38},{header:'แหล่งซื้อ',key:'source',width:28},{header:'การชำระเงิน',key:'paymentMethod',width:18},{header:'หมายเหตุ',key:'note',width:32},{header:'จำนวน',key:'qty',width:12},{header:'หน่วย',key:'itemUnit',width:14},{header:'ราคาต่อหน่วย',key:'unitPrice',width:16},{header:'ประเภทภาษี',key:'vatType',width:13},{header:'ก่อน VAT',key:'base',width:16},{header:'VAT',key:'tax',width:14},{header:'รวมสุทธิ',key:'total',width:16},{header:'ยอดนับรายงาน',key:'eligible',width:18}];
 for(const po of report.rows)for(const item of po.items)sheet.addRow({po:po.po_number,date:po.po_date,requester:po.requester_name,department:item.department||po.department||'',status:statuses[po.status]||po.status,itemStatus:itemStatusLabels[item.state]||item.state,name:item.name,spec:item.spec,source:item.source,paymentMethod:paymentLabels[item.payment_method]||'ไม่ระบุ',note:item.note||'',qty:Number(item.qty),itemUnit:item.unit||'ชิ้น',unitPrice:Number(item.unit_price),vatType:item.vat?'VAT 7%':'NON VAT',base:item.base_cents/100,tax:item.tax_cents/100,total:item.total_cents/100,eligible:itemEligible(item)?item.total_cents/100:0});
 for(const key of ['unitPrice','base','tax','total','eligible'])sheet.getColumn(key).eachCell((cell,row)=>{if(row>1)cell.numFmt='฿#,##0.00';});sheet.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};sheet.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF164B49'}};sheet.autoFilter={from:{row:1,column:1},to:{row:1,column:sheet.columnCount}};sheet.eachRow(row=>{row.alignment={vertical:'top',wrapText:true};});return workbook;
}
export async function createPreviewDownload(report,month,ExcelJS=globalThis.ExcelJS){const workbook=await buildPreviewWorkbook(report,month,ExcelJS),buffer=await workbook.xlsx.writeBuffer(),blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});return {url:URL.createObjectURL(blob),filename:`PO-The-Grands-${month}.xlsx`};}
export function derivePreviewReport(rows,month){const actor={id:'preview-primary',role:'office',can_export_report:true,display_name:'ฝ่ายจัดซื้อหลัก'},service=createPreviewService({fixtures:rows});return service.report(month,actor);}
